"""The fixed eagle camera's view: where world points fall in its image (design plan 14.1, decisions-log M153).

    m = view_margins(model, data, points)      # {point name: margin}, the margin to the nearest image edge as a fraction of the image (-1: closer than near_depth to the camera)
    ok = in_view(model, data, points)           # every point at least `margin` (STANCE_REQUIREMENTS["view_min_margin"], 10 %) from every edge

The camera is fixed to the torso, so the view depends only on where the robot stands and on the pedestal height. Every camera check is "inside the fixed view": the targets inside the image with the 10 %
edge margin (this module) and not hidden (src/stance_checks.OcclusionMeter). Only kinematics are used: `data` must have had mj_forward / mj_kinematics (and mj_camlight for the camera pose).

Contents:
    view_margins, in_view.
"""

import math

import mujoco
import numpy as np

from src.task_config import STANCE_REQUIREMENTS

NEAR_DEPTH = 0.05      # m: points closer to the camera than this count as not visible


def view_margins(model, data, points, camera="eagle_cam"):
    """The margin of each point in the camera's image.

    Args:
        model (mujoco.MjModel): The model.
        data (mujoco.MjData): Its data with the camera's pose up to date (mujoco.mj_forward).
        points (dict or array-like): {name: world (x, y, z)} or a sequence of points (named "p0", "p1", ...).
        camera (str): The camera. Defaults to "eagle_cam".

    Returns:
        dict: {point name: margin}: the distance to the nearest image edge as a fraction of the image width or height (0.5 at the centre, 0 on an edge, negative outside, -1 for a point closer than
        NEAR_DEPTH to the camera or behind it).
    """
    c = model.camera(camera).id
    pos, R = data.cam_xpos[c].copy(), data.cam_xmat[c].reshape(3, 3)
    W, H = [float(v) for v in model.cam_resolution[c]]
    names = list(points) if isinstance(points, dict) else [f"p{i}" for i in range(len(points))]
    P = np.array([points[n] for n in names] if isinstance(points, dict) else points, float).reshape(-1, 3)
    pc = (P - pos) @ R                                   # the camera looks along its -z, +y up, +x right
    depth = -pc[:, 2]
    th = math.tan(math.radians(float(model.cam_fovy[c])) / 2)
    safe = np.maximum(depth, 1e-6)
    u, v = pc[:, 0] / safe / (th * W / H), pc[:, 1] / safe / th
    m = np.where(depth < NEAR_DEPTH, -1.0, np.minimum((1 - np.abs(u)) / 2, (1 - np.abs(v)) / 2))
    return {n: float(m[i]) for i, n in enumerate(names)}


def in_view(model, data, points, margin=STANCE_REQUIREMENTS["view_min_margin"], camera="eagle_cam"):
    """Whether every point is inside the image with at least `margin` to every edge.

    Returns:
        tuple: (bool, dict): the verdict and view_margins' margins.
    """
    mg = view_margins(model, data, points, camera)
    return all(v >= margin - 1e-9 for v in mg.values()), mg
